import numpy as np
from scipy.optimize import minimize
import os

N = 26

def construct_packing() -> tuple:
    try:
        base_centers = np.loadtxt('storage/episteme/sota_base_centers.txt')
        base_radii = np.loadtxt('storage/episteme/sota_base_radii.txt')
    except Exception:
        return np.array([[0.5, 0.5]] * 26), np.array([0.05] * 26)

    # --- Stage 1: Global Shrink Perturbation ---
    shrink_factor = 0.995 # Shrink all radii by 0.5%
    perturbed_radii = base_radii * shrink_factor

    # --- Stage 2: SLSQP Refinement ---
    def cr_to_z(c, r): return np.concatenate([c.flatten(), r])
    def z_to_cr(z): return z[:N*2].reshape(N, 2), z[N*2:]
    def objective(z): return -np.sum(z[N*2:])
    def ineq_boundary(z):
        c, r = z_to_cr(z)
        return np.concatenate([c[:,0] - r, 1 - (c[:,0] + r), c[:,1] - r, 1 - (c[:,1] + r)])
    def ineq_nonoverlap(z):
        c, r = z_to_cr(z)
        diff = c[:, None, :] - c[None, :, :]; dist = np.sqrt(np.sum(diff**2, axis=-1))
        iu = np.triu_indices(N, 1); return dist[iu] - (r[iu[0]] + r[iu[1]])
    def _ensure_validity(c, r):
        for _ in range(10):
            v=0
            for i in range(N):
                for j in range(i + 1, N):
                    dist = np.linalg.norm(c[i] - c[j]); rad_sum = r[i] + r[j]
                    if dist < rad_sum: v+=1; scale = (dist/rad_sum)*(1.0-1e-9); r[i]*=scale; r[j]*=scale
            if v==0: break
        r_vec = r.reshape(-1, 1)
        c = np.clip(c, r_vec, 1.0 - r_vec)
        return c, np.maximum(r, 0)

    # Use the same centers but the shrunken radii as the starting point
    initial_z = cr_to_z(base_centers, perturbed_radii)
    bounds = [(0,1)]*N*2 + [(1e-6, 0.5)]*N
    constraints = [{'type': 'ineq', 'fun': ineq_boundary}, {'type': 'ineq', 'fun': ineq_nonoverlap}]

    res = minimize(objective, initial_z, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter': 2000, 'ftol': 1e-10})

    if res.success:
        c_res, r_res = z_to_cr(res.x)
        return _ensure_validity(c_res, r_res)
    else:
        # Fallback if SLSQP fails, return the original SOTA packing
        return _ensure_validity(base_centers, base_radii)
